\label{expandingprop} (cf. Claim of I.2.3)
If $\bar\lambda(g(t))\le0$ at some time, then $d\bar\lambda/dt\ge0$.
\end{proposition}
\begin{proof}
\sketch
\begin{equation}
{d\bar\lambda\over dt}=V^{2/n}{d\lambda\over dt}-{2\over n}V^{(2-n)/n}\lambda\int_MR,dV.
\end{equation}
